53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	};
65	
66	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
67	
68	const quote = (step: QuoteStep): QuoteResult => {
69	  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
70	  const premiumBeforeRounding =
71	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE;
72	  return { premium: Math.ceil(premiumBeforeRounding) };
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioOutput => {
76	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
77	};
